var greeter = new Greeter(new SystemClock());
Console.WriteLine(greeter.Greet("Ada"));

interface IClock
{
    DateTime Now { get; }
}

class SystemClock : IClock
{
    public DateTime Now => DateTime.Now;
}

class Greeter(IClock clock)
{
    public string Greet(string name) => $"Hello, {name}!";
}
